/// A load-pattern fixture assembled from guest program configuration and a plan.
///
/// Fixtures are intentionally small examples of guest-program-plus-scenario-
/// parameter constructions. They do not introduce a host application traffic
/// generator; spike bursts and correlated failures use existing [`Plan`]
/// primitives.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct GuestWorkloadLoadPatternFixture {
    pattern: GuestWorkloadPattern,
    spike_mode: Option<GuestWorkloadSpikeMode>,
    time_source: Option<GuestWorkloadTimeSource>,
    world: World,
    plan: Plan,
}

impl GuestWorkloadLoadPatternFixture {
    /// Builds the steady-load fixture.
    ///
    /// # Errors
    ///
    /// Returns a world validation error if the fixture topology or reserved
    /// command-line parameters are invalid.
    pub fn steady() -> Result<Self, EngineError> {
        let cmdline = workload_pattern_cmdline(
            "console=ttyS0 rate_per_sec=100",
            GuestWorkloadPattern::Steady,
            None,
            None,
        );
        let world = World::from_nodes(vec![workload_pattern_node("client", cmdline)])?;
        Ok(Self {
            pattern: GuestWorkloadPattern::Steady,
            spike_mode: None,
            time_source: None,
            world,
            plan: Plan::empty(),
        })
    }

    /// Builds the virtual-time-rate spike fixture.
    ///
    /// # Errors
    ///
    /// Returns a world validation error if the fixture topology or reserved
    /// command-line parameters are invalid.
    pub fn spike_virtual_time_rate() -> Result<Self, EngineError> {
        let cmdline = workload_pattern_cmdline(
            concat!(
                "console=ttyS0 base_rate_per_sec=10 peak_rate_per_sec=500 ",
                "spike_at_ticks=50 spike_duration_ticks=10"
            ),
            GuestWorkloadPattern::Spike,
            Some(GuestWorkloadSpikeMode::VirtualTimeRate),
            Some(GuestWorkloadTimeSource::VirtualTime),
        );
        let world = World::from_nodes(vec![workload_pattern_node("client", cmdline)])?;
        Ok(Self {
            pattern: GuestWorkloadPattern::Spike,
            spike_mode: Some(GuestWorkloadSpikeMode::VirtualTimeRate),
            time_source: Some(GuestWorkloadTimeSource::VirtualTime),
            world,
            plan: Plan::empty(),
        })
    }

    /// Builds the planned `StartNode` burst spike fixture.
    ///
    /// # Errors
    ///
    /// Returns a world or event-graph validation error if the fixture topology,
    /// reserved command-line parameters, or planned start action are invalid.
    pub fn spike_start_node_burst() -> Result<Self, EngineError> {
        let steady_cmdline = workload_pattern_cmdline(
            "console=ttyS0 base_rate_per_sec=10",
            GuestWorkloadPattern::Spike,
            Some(GuestWorkloadSpikeMode::StartNodeBurst),
            Some(GuestWorkloadTimeSource::VirtualTime),
        );
        let burst_cmdline = workload_pattern_cmdline(
            "console=ttyS0 burst_rate_per_sec=500",
            GuestWorkloadPattern::Spike,
            Some(GuestWorkloadSpikeMode::StartNodeBurst),
            Some(GuestWorkloadTimeSource::VirtualTime),
        );
        let burst_node = NodeId {
            name: String::from("client-burst"),
        };
        let hold_tag = FaultTag::from_name("burst-not-yet-joined");
        let world = World::from_nodes(vec![
            workload_pattern_node("client-steady", steady_cmdline),
            workload_pattern_node("client-burst", burst_cmdline),
        ])?;
        let graph = EventGraph::new_for_world(
            vec![
                Event::once(
                    EventId::from_name("hold-burst-at-genesis"),
                    None,
                    Action::inject_fault(
                        hold_tag.clone(),
                        MembershipFault::NotYetJoined {
                            node: burst_node.clone(),
                        },
                    ),
                ),
                Event::once(
                    EventId::from_name("start-burst-at-vt"),
                    Some(Predicate::at(VirtualTime { ticks: 50 })),
                    Action::group(vec![
                        Action::heal_fault(hold_tag),
                        Action::start_node(burst_node),
                    ]),
                ),
            ],
            &world,
        )
        .map_err(event_graph_plan_error)?;
        let plan = Plan::from_event_graph_for_world(&world, graph)?;
        Ok(Self {
            pattern: GuestWorkloadPattern::Spike,
            spike_mode: Some(GuestWorkloadSpikeMode::StartNodeBurst),
            time_source: Some(GuestWorkloadTimeSource::VirtualTime),
            world,
            plan,
        })
    }

    /// Builds the cardinality-growth fixture.
    ///
    /// # Errors
    ///
    /// Returns a world validation error if the fixture topology or reserved
    /// command-line parameters are invalid.
    pub fn cardinality_growth() -> Result<Self, EngineError> {
        let cmdline = workload_pattern_cmdline(
            concat!(
                "console=ttyS0 initial_keys=8 key_growth_per_sec=4 ",
                "key_cap=1024"
            ),
            GuestWorkloadPattern::CardinalityGrowth,
            None,
            Some(GuestWorkloadTimeSource::VirtualTime),
        );
        let world = World::from_nodes(vec![workload_pattern_node("client", cmdline)])?;
        Ok(Self {
            pattern: GuestWorkloadPattern::CardinalityGrowth,
            spike_mode: None,
            time_source: Some(GuestWorkloadTimeSource::VirtualTime),
            world,
            plan: Plan::empty(),
        })
    }

    /// Builds the correlated-failure-campaign fixture.
    ///
    /// # Errors
    ///
    /// Returns a world or fault-plan validation error if the fixture topology,
    /// reserved command-line parameters, or fault campaign is invalid.
    pub fn correlated_failure_campaign() -> Result<Self, EngineError> {
        let left = workload_pattern_node(
            "client-a",
            workload_pattern_cmdline(
                "console=ttyS0 rate_per_sec=50",
                GuestWorkloadPattern::CorrelatedFailure,
                None,
                None,
            ),
        );
        let right = workload_pattern_node(
            "client-b",
            workload_pattern_cmdline(
                "console=ttyS0 rate_per_sec=50",
                GuestWorkloadPattern::CorrelatedFailure,
                None,
                None,
            ),
        );
        let link = LinkDef::new(left.id.clone(), right.id.clone())?;
        let link_id = workload_pattern_link_id(&link);
        let crash_node = right.id.clone();
        let world = World::from_nodes_and_links(vec![left, right], vec![link])?;
        let entries = vec![
            FaultPlanEntry::At {
                at: VirtualTime { ticks: 20 },
                duration: FaultDuration::from_nanos(10),
                tag: FaultTag::from_name("correlated-partition"),
                fault: Fault::Network(NetworkFault::Partition {
                    link: link_id.clone(),
                    direction: PartitionDirection::Bidirectional,
                }),
            },
            FaultPlanEntry::At {
                at: VirtualTime { ticks: 20 },
                duration: FaultDuration::from_nanos(10),
                tag: FaultTag::from_name("correlated-loss"),
                fault: Fault::Network(NetworkFault::Loss {
                    link: link_id,
                    rate: FaultRateBasisPoints::from_basis_points(2_500)?,
                }),
            },
            FaultPlanEntry::PermanentAt {
                at: VirtualTime { ticks: 20 },
                tag: FaultTag::from_name("correlated-crash"),
                fault: Fault::Node(NodeFault::Crash {
                    node: crash_node,
                    restart: RestartPolicy::StayDown,
                }),
            },
        ];
        let plan = Plan::from_fault_plan_for_world(&world, FaultPlan::from_entries(entries))?;
        Ok(Self {
            pattern: GuestWorkloadPattern::CorrelatedFailure,
            spike_mode: None,
            time_source: None,
            world,
            plan,
        })
    }

    /// Returns the fixture's load pattern.
    #[must_use]
    pub fn pattern(&self) -> GuestWorkloadPattern {
        self.pattern
    }

    /// Returns the fixture's spike mode, when the pattern is a spike fixture.
    #[must_use]
    pub fn spike_mode(&self) -> Option<GuestWorkloadSpikeMode> {
        self.spike_mode
    }

    /// Returns the fixture's load-shape time source, when the pattern varies over time.
    #[must_use]
    pub fn time_source(&self) -> Option<GuestWorkloadTimeSource> {
        self.time_source
    }

    /// Returns the content-addressed world assembled by this fixture.
    #[must_use]
    pub fn world(&self) -> &World {
        &self.world
    }

    /// Returns the plan assembled by this fixture.
    #[must_use]
    pub fn plan(&self) -> &Plan {
        &self.plan
    }

    /// Builds a scenario definition for this fixture with empty properties.
    ///
    /// # Errors
    ///
    /// Returns a plan validation error if the fixture plan no longer layers over
    /// its world.
    pub fn scenario_def(&self, seed: Seed) -> Result<ScenarioDef, EngineError> {
        self.world.scenario_def_with_plan_properties_and_seed(
            &self.plan,
            &Properties::empty(),
            seed,
        )
    }
}

/// The role Crucible plays for application workload traffic.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum WorkloadEngineRole {
    /// The engine only observes black-box effects and steers via model-level controls.
    ObservationAndSteeringOnly,
}

impl WorkloadEngineRole {
    /// Returns whether this role originates application-level traffic.
    #[must_use]
    pub const fn originates_application_traffic(self) -> bool {
        match self {
            Self::ObservationAndSteeringOnly => false,
        }
    }

    /// Returns whether this role permits a host-side traffic injector.
    #[must_use]
    pub const fn permits_host_side_traffic_injector(self) -> bool {
        match self {
            Self::ObservationAndSteeringOnly => false,
        }
    }
}

/// A handle to an immutable scenario definition.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub struct ScenarioDef {
    /// The content address of the scenario definition.
    id: ContentHash,
    /// The root entropy carried by this scenario definition.
    seed: Seed,
    /// The maximum number of app-random decisions admitted for one run.
    app_random_draw_cap: u64,
}

impl ScenarioDef {
    /// Returns the content address of this scenario definition.
    #[must_use]
    pub fn id(&self) -> ContentHash {
        self.id
    }

    /// Returns the root entropy carried by this scenario definition.
    #[must_use]
    pub fn seed(&self) -> Seed {
        self.seed
    }

    /// Returns the configured app-random draw cap for this scenario.
    #[must_use]
    pub fn app_random_draw_cap(&self) -> u64 {
        self.app_random_draw_cap
    }

    /// Rebuilds a scenario definition handle from trusted content-addressed identity fields.
    ///
    /// This is a transport and artifact decoding helper for cases that already
    /// received a validated scenario definition elsewhere and only need to
    /// rehydrate the identity-bearing execution handle. Scenario authors should
    /// use [`ScenarioDefForm`] or the builder APIs instead so component hashes
    /// are derived from canonical scenario content.
    #[must_use]
    pub const fn from_trusted_identity(
        id: ContentHash,
        seed: Seed,
        app_random_draw_cap: u64,
    ) -> Self {
        Self {
            id,
            seed,
            app_random_draw_cap,
        }
    }

    /// Builds a scenario definition from canonical material.
    ///
    /// This helper is the engine-side content-addressing entry point for
    /// backend-produced canonical material.
    #[must_use]
    pub fn from_canonical_material(domain: &str, material: &str) -> Self {
        Self::from_canonical_material_with_seed(domain, material, Seed::default())
    }

    /// Builds a scenario definition from canonical material and root seed.
    ///
    /// This helper is the compatibility entry point for backend-produced
    /// canonical material when the caller also has the scenario seed component.
    /// The seed is included in the returned content address so it cannot drift
    /// from scenario identity.
    #[must_use]
    pub fn from_canonical_material_with_seed(domain: &str, material: &str, seed: Seed) -> Self {
        Self::from_canonical_material_with_seed_and_app_random_draw_cap(
            domain,
            material,
            seed,
            DEFAULT_APP_RANDOM_DRAW_CAP,
        )
    }

    /// Builds a scenario definition from canonical material, root seed, and
    /// app-random draw cap.
    ///
    /// The cap is included in the returned content address so app-random policy
    /// cannot drift from scenario identity.
    #[must_use]
    pub fn from_canonical_material_with_seed_and_app_random_draw_cap(
        domain: &str,
        material: &str,
        seed: Seed,
        app_random_draw_cap: u64,
    ) -> Self {
        let material = format!(
            "{material}\n{}\n{}",
            seed_material(seed),
            app_random_draw_cap_material(app_random_draw_cap)
        );
        Self {
            id: ContentHash::from_canonical_material(domain, &material),
            seed,
            app_random_draw_cap,
        }
    }

    /// Builds an opaque scenario definition from already-addressed components.
    ///
    /// This is the compatibility path for API adapters that receive an inline
    /// scenario handle over a transport before the full scenario form lands on
    /// the wire. Callers are responsible for supplying the content address that
    /// corresponds to the seed and app-random policy.
    #[must_use]
    pub fn from_content_hash_seed_and_app_random_draw_cap(
        id: ContentHash,
        seed: Seed,
        app_random_draw_cap: u64,
    ) -> Self {
        Self {
            id,
            seed,
            app_random_draw_cap,
        }
    }
}

impl World {
    /// Builds an opaque world handle from an already-computed content address.
    ///
    /// This is the compatibility path for backend tests and adapters that do
    /// not yet carry full spatial-graph node material.
    #[must_use]
    pub fn from_content_hash(id: ContentHash) -> Self {
        Self {
            id,
            nodes: Vec::new(),
            links: Vec::new(),
        }
    }

    /// Builds a world from an already-recorded identity and validated topology.
    ///
    /// This compatibility path lets adapters preserve an external world handle
    /// while still enforcing the same static topology invariants as
    /// [`World::from_nodes_and_links`]. Non-empty logical worlds derive
    /// [`ScenarioDef`] and bake identity from their node/link material rather
    /// than this recorded handle.
    ///
    /// # Errors
    ///
    /// Returns the same topology, ready-point, and launch-input validation
    /// errors as [`World::from_nodes_and_links`].
    pub fn from_recorded_parts(
        id: ContentHash,
        nodes: Vec<WorldNode>,
        links: Vec<LinkDef>,
    ) -> Result<Self, EngineError> {
        let nodes = canonical_world_nodes(&nodes);
        let links = canonical_world_links(&links);
        validate_world_nodes(&nodes)?;
        validate_world_links(&nodes, &links)?;
        Ok(Self { id, nodes, links })
    }

    /// Returns the world content address carried by this handle.
    #[must_use]
    pub fn id(&self) -> ContentHash {
        self.id
    }

    /// Returns this world's immutable node topology.
    #[must_use]
    pub fn nodes(&self) -> &[WorldNode] {
        &self.nodes
    }

    /// Returns this world's immutable logical links.
    #[must_use]
    pub fn links(&self) -> &[LinkDef] {
        &self.links
    }

    /// Returns the workload config-tree exports declared by world nodes.
    ///
    /// The declarations are derived from validated `wcfg=...` scenario
    /// parameters in node command lines, so the returned config-tree refs are
    /// part of the world's content-addressed material. Rootfs-backed entries are
    /// additionally validated to match the node's read-only `root_image`.
    #[must_use]
    pub fn workload_config_trees(&self) -> Vec<WorldWorkloadConfigTree> {
        self.nodes
            .iter()
            .filter_map(|node| {
                node.guest_workload_config_tree()
                    .map(|config| WorldWorkloadConfigTree {
                        node: node.id.clone(),
                        config,
                    })
            })
            .collect()
    }

    /// Builds a canonical world from node ready-point configuration.
    ///
    /// Nodes are sorted by [`NodeId`] before hashing so authoring order does not
    /// affect the world identity.
    ///
    /// # Errors
    ///
    /// Returns [`EngineError::DuplicateWorldNodeId`] when a node id appears
    /// more than once, [`EngineError::WhiteBoxReadyPointWithoutOptIn`] when a
    /// node selects [`ReadyPoint::AgentSignal`] without enabling
    /// [`WhiteBoxPolicy::Enabled`],
    /// [`EngineError::ReadyPointNetworkIdleWindowZero`] when a node selects an
    /// empty network-idle window,
    /// [`EngineError::ReadyPointNetworkIdleWithoutLinks`] when a node selects
    /// network-idle readiness without any incident links,
    /// [`EngineError::ReadyPointConsoleMarkerEmpty`] when a node selects an
    /// empty console marker. Returns
    /// [`EngineError::WorldNodeSmpVcpuCountZero`],
    /// [`EngineError::WorldNodeMemoryMibZero`], or
    /// [`EngineError::WorldNodeIcountShiftTooLarge`] when a node's fixed launch
    /// fields are invalid. Returns workload scenario-parameter validation errors
    /// when reserved workload, seed, scalar-parameter, config-tree, load-pattern,
    /// spike-mode, or time-source command-line config is malformed, duplicated,
    /// unsupported, or inconsistent with its declared delivery surface.
    pub fn from_nodes(nodes: Vec<WorldNode>) -> Result<Self, EngineError> {
        Self::from_nodes_and_links(nodes, Vec::new())
    }

    /// Builds a canonical world from node and link topology.
    ///
    /// Nodes are sorted by [`NodeId`] and links are sorted by endpoint pair
    /// before hashing so authoring order does not affect world identity.
    ///
    /// # Errors
    ///
    /// Returns [`EngineError::DuplicateWorldNodeId`] when a node id appears
    /// more than once, [`EngineError::WhiteBoxReadyPointWithoutOptIn`] when a
    /// node selects [`ReadyPoint::AgentSignal`] without enabling
    /// [`WhiteBoxPolicy::Enabled`],
    /// [`EngineError::ReadyPointNetworkIdleWindowZero`] when a node selects an
    /// empty network-idle window,
    /// [`EngineError::ReadyPointNetworkIdleWithoutLinks`] when a node selects
    /// network-idle readiness without any incident links,
    /// [`EngineError::ReadyPointConsoleMarkerEmpty`] when a node selects an
    /// empty console marker,
    /// [`EngineError::WorldNodeSmpVcpuCountZero`],
    /// [`EngineError::WorldNodeMemoryMibZero`], or
    /// [`EngineError::WorldNodeIcountShiftTooLarge`] when a node's fixed launch
    /// fields are invalid, workload scenario-parameter validation errors when
    /// reserved workload, seed, scalar-parameter, config-tree, load-pattern,
    /// spike-mode, or time-source command-line config is malformed, duplicated,
    /// unsupported, or inconsistent with its declared delivery surface,
    /// [`EngineError::WorldLinkUnknownNode`] when a
    /// link references an undeclared node, [`EngineError::WorldLinkSelfLoop`]
    /// when a link's endpoints are equal, or [`EngineError::DuplicateWorldLink`]
    /// when a canonical endpoint pair appears more than once. Returns
    /// [`EngineError::WorldLinkLatencyBelowFloor`] or
    /// [`EngineError::WorldLinkJitterBelowLatencyFloor`] when a link's
    /// transport configuration violates the latency floor.
    pub fn from_nodes_and_links(
        nodes: Vec<WorldNode>,
        links: Vec<LinkDef>,
    ) -> Result<Self, EngineError> {
        let nodes = canonical_world_nodes(&nodes);
        let links = canonical_world_links(&links);
        validate_world_nodes(&nodes)?;
        validate_world_links(&nodes, &links)?;
        Ok(Self {
            id: ContentHash::from_canonical_material(
                "crucible.model.world.v1",
                &world_material(&nodes, &links),
            ),
            nodes,
            links,
        })
    }

    /// Validates the world's ready-point policy configuration.
    ///
    /// # Errors
    ///
    /// Returns [`EngineError::DuplicateWorldNodeId`] when a node id appears
    /// more than once, [`EngineError::WhiteBoxReadyPointWithoutOptIn`] when a
    /// node selects [`ReadyPoint::AgentSignal`] without enabling
    /// [`WhiteBoxPolicy::Enabled`],
    /// [`EngineError::ReadyPointNetworkIdleWindowZero`] when a node selects an
    /// empty network-idle window,
    /// [`EngineError::ReadyPointNetworkIdleWithoutLinks`] when a node selects
    /// network-idle readiness without any incident links,
    /// [`EngineError::ReadyPointConsoleMarkerEmpty`] when a node selects an
    /// empty console marker,
    /// [`EngineError::WorldNodeSmpVcpuCountZero`],
    /// [`EngineError::WorldNodeMemoryMibZero`], or
    /// [`EngineError::WorldNodeIcountShiftTooLarge`] when a node's fixed launch
    /// fields are invalid, workload scenario-parameter validation errors when
    /// reserved workload, seed, scalar-parameter, config-tree, load-pattern,
    /// spike-mode, or time-source command-line config is malformed, duplicated,
    /// unsupported, or inconsistent with its declared delivery surface, or a link
    /// validation error from [`World::validate_topology`].
    pub fn validate_ready_point_policies(&self) -> Result<(), EngineError> {
        self.validate_topology()
    }

    /// Validates the world's canonical node/link topology.
    ///
    /// # Errors
    ///
    /// Returns [`EngineError::DuplicateWorldNodeId`] when a node id appears
    /// more than once, [`EngineError::WhiteBoxReadyPointWithoutOptIn`] when a
    /// node selects [`ReadyPoint::AgentSignal`] without enabling
    /// [`WhiteBoxPolicy::Enabled`],
    /// [`EngineError::ReadyPointNetworkIdleWindowZero`] when a node selects an
    /// empty network-idle window,
    /// [`EngineError::ReadyPointNetworkIdleWithoutLinks`] when a node selects
    /// network-idle readiness without any incident links,
    /// [`EngineError::ReadyPointConsoleMarkerEmpty`] when a node selects an
    /// empty console marker,
    /// [`EngineError::WorldNodeSmpVcpuCountZero`],
    /// [`EngineError::WorldNodeMemoryMibZero`], or
    /// [`EngineError::WorldNodeIcountShiftTooLarge`] when a node's fixed launch
    /// fields are invalid, workload scenario-parameter validation errors when
    /// reserved workload, seed, scalar-parameter, config-tree, load-pattern,
    /// spike-mode, or time-source command-line config is malformed, duplicated,
    /// unsupported, or inconsistent with its declared delivery surface,
    /// [`EngineError::WorldLinkUnknownNode`] when a
    /// link references an undeclared node, [`EngineError::WorldLinkSelfLoop`]
    /// when a link's endpoints are equal, or [`EngineError::DuplicateWorldLink`]
    /// when a canonical endpoint pair appears more than once. Returns
    /// [`EngineError::WorldLinkLatencyBelowFloor`] or
    /// [`EngineError::WorldLinkJitterBelowLatencyFloor`] when a link's
    /// transport configuration violates the latency floor.
    pub fn validate_topology(&self) -> Result<(), EngineError> {
        validate_world_nodes(&self.nodes)?;
        validate_world_links(&self.nodes, &self.links)
    }

    /// Derives the static topology products that are fixed by this world.
    ///
    /// The returned participant set, per-entity decision-RNG streams,
    /// scheduler-lookahead graph, and bake-node set are functions only of the
    /// world's node/link topology. They do not take a [`Schedule`] and therefore
    /// cannot vary with a schedule prefix.
    #[must_use]
    pub fn static_topology(&self) -> WorldStaticTopology {
        WorldStaticTopology {
            participants: world_participants(self),
            rng_streams: world_rng_streams(self),
            lookahead_graph: world_lookahead_edges(self),
            bake_nodes: world_bake_nodes(self),
        }
    }

    /// Builds the canonical genesis scenario definition for this world, empty plan,
    /// empty properties, and the default seed.
    ///
    /// Later builder work provides the explicit authoring surface; until then
    /// this helper composes the independently hashed `World`, empty [`Plan`],
    /// empty [`Properties`], and default [`Seed`] components.
    #[must_use]
    pub fn scenario_def(&self) -> ScenarioDef {
        self.scenario_def_from_components(&Plan::empty(), &Properties::empty(), Seed::default())
    }

    /// Builds the canonical scenario definition for this world, plan, and empty
    /// properties.
    ///
    /// # Errors
    ///
    /// Returns [`EngineError::PlanFaultUnknownNode`],
    /// [`EngineError::PlanFaultUnknownLink`],
    /// [`EngineError::PlanHealUnknownTag`],
    /// [`EngineError::PlanHealBeforeActivate`], or
    /// [`EngineError::PlanNotYetJoinedAfterStart`] when `plan` cannot be
    /// layered over this world's static topology.
    pub fn scenario_def_with_plan(&self, plan: &Plan) -> Result<ScenarioDef, EngineError> {
        plan.validate_for_world(self)?;
        Ok(self.scenario_def_from_components(plan, &Properties::empty(), Seed::default()))
    }

    /// Builds the canonical scenario definition for this world, empty plan, and
    /// properties.
    ///
    /// # Errors
    ///
    /// Returns [`EngineError::PropertyDuplicateAssertionId`],
    /// [`EngineError::PropertyPredicateUnknownNode`], or
    /// [`EngineError::PropertyPredicateEmptyCompound`], or
    /// [`EngineError::PropertyPredicateTriggerOnly`] when `properties` cannot be
    /// layered over this world's static topology.
    pub fn scenario_def_with_properties(
        &self,
        properties: &Properties,
    ) -> Result<ScenarioDef, EngineError> {
        let plan = Plan::empty();
        let properties = resolve_properties_dsl_for_context(self, &plan, properties)?;
        properties.validate_for_world(self)?;
        Ok(self.scenario_def_from_components(&plan, &properties, Seed::default()))
    }

    /// Builds the canonical scenario definition for this world, plan, and
    /// properties, using the default seed.
    ///
    /// # Errors
    ///
    /// Returns a plan validation error when `plan` cannot be layered over this
    /// world's static topology, or a property validation error when `properties`
    /// names undeclared predicate nodes or otherwise violates the declarative
    /// property model.
    pub fn scenario_def_with_plan_and_properties(
        &self,
        plan: &Plan,
        properties: &Properties,
    ) -> Result<ScenarioDef, EngineError> {
        let properties = resolve_properties_dsl_for_context(self, plan, properties)?;
        match plan.event_graph() {
            Some(_) => {
                properties.validate_for_world(self)?;
                plan.validate_for_world_with_properties(self, &properties)?;
            }
            None => {
                plan.validate_for_world(self)?;
                properties.validate_for_world(self)?;
            }
        }
        Ok(self.scenario_def_from_components(plan, &properties, Seed::default()))
    }

    /// Builds the canonical scenario definition for this world, empty plan,
    /// empty properties, and `seed`.
    #[must_use]
    pub fn scenario_def_with_seed(&self, seed: Seed) -> ScenarioDef {
        self.scenario_def_from_components(&Plan::empty(), &Properties::empty(), seed)
    }

    /// Builds the canonical scenario definition for this world, empty plan,
    /// empty properties, `seed`, and app-random draw cap.
    #[must_use]
    pub fn scenario_def_with_seed_and_app_random_draw_cap(
        &self,
        seed: Seed,
        app_random_draw_cap: u64,
    ) -> ScenarioDef {
        self.scenario_def_from_components_with_app_random_draw_cap(
            &Plan::empty(),
            &Properties::empty(),
            seed,
            app_random_draw_cap,
        )
    }

    /// Builds the canonical scenario definition for this world, plan,
    /// properties, and seed.
    ///
    /// # Errors
    ///
    /// Returns a plan validation error when `plan` cannot be layered over this
    /// world's static topology, or a property validation error when `properties`
    /// names undeclared predicate nodes or otherwise violates the declarative
    /// property model.
    pub fn scenario_def_with_plan_properties_and_seed(
        &self,
        plan: &Plan,
        properties: &Properties,
        seed: Seed,
    ) -> Result<ScenarioDef, EngineError> {
        let properties = resolve_properties_dsl_for_context(self, plan, properties)?;
        match plan.event_graph() {
            Some(_) => {
                properties.validate_for_world(self)?;
                plan.validate_for_world_with_properties(self, &properties)?;
            }
            None => {
                plan.validate_for_world(self)?;
                properties.validate_for_world(self)?;
            }
        }
        Ok(self.scenario_def_from_components(plan, &properties, seed))
    }

    /// Derives this world's per-entity decision-RNG stream seeds from `seed`.
    #[must_use]
    pub fn seeded_rng_streams(&self, seed: Seed) -> Vec<SeededRngStream> {
        self.static_topology()
            .rng_streams
            .into_iter()
            .map(|stream| SeededRngStream {
                seed: seed.stream_seed(&stream),
                stream,
            })
            .collect()
    }

    /// Serializes this world component as deterministic TOML.
    ///
    /// # Errors
    ///
    /// Returns [`EngineError::ScenarioSerialization`] if the TOML renderer rejects
    /// the internal DTO shape.
    pub fn to_canonical_toml(&self) -> Result<String, EngineError> {
        toml::to_string(&world_to_toml(self)).map_err(|source| {
            scenario_serialization_error(format!("serialize world TOML: {source}"))
        })
    }

    /// Parses and validates a deterministic TOML world component.
    ///
    /// # Errors
    ///
    /// Returns [`EngineError::ScenarioSerialization`] for malformed TOML or an id
    /// mismatch, or a world validation error for invalid topology, launch fields,
    /// ready points, or workload scenario-parameter delivery.
    pub fn from_canonical_toml(input: &str) -> Result<Self, EngineError> {
        validate_no_host_path_image_refs_in_toml(input)?;
        let toml = toml::from_str::<WorldToml>(input).map_err(|source| {
            scenario_serialization_error(format!("parse world TOML: {source}"))
        })?;
        world_from_toml(toml)
    }

    /// Serializes this world component as compact binary.
    #[must_use]
    pub fn to_compact_binary(&self) -> Vec<u8> {
        let mut writer = ScenarioBinaryWriter::new(WORLD_BINARY_MAGIC);
        write_world_binary(self, &mut writer);
        writer.finish()
    }

    /// Parses and validates a compact binary world component.
    ///
    /// # Errors
    ///
    /// Returns [`EngineError::ScenarioSerialization`] for malformed binary input
    /// or an id mismatch, or a world validation error for invalid topology,
    /// launch fields, ready points, or workload scenario-parameter delivery.
    pub fn from_compact_binary(bytes: &[u8]) -> Result<Self, EngineError> {
        let mut reader = ScenarioBinaryReader::new(bytes, WORLD_BINARY_MAGIC)?;
        let world = read_world_binary(&mut reader)?;
        reader.finish()?;
        Ok(world)
    }

    /// Returns the canonical bytes used to compute this world's content address.
    #[must_use]
    pub fn canonical_bytes(&self) -> Vec<u8> {
        world_material(
            &canonical_world_nodes(&self.nodes),
            &canonical_world_links(&self.links),
        )
        .into_bytes()
    }

    fn scenario_def_from_components(
        &self,
        plan: &Plan,
        properties: &Properties,
        seed: Seed,
    ) -> ScenarioDef {
        let material = scenario_world_plan_properties_seed_material(self, plan, properties, seed);
        ScenarioDef {
            id: ContentHash::from_canonical_material(
                "crucible.model.world-plan-properties-seed-scenario.v1",
                &material,
            ),
            seed,
            app_random_draw_cap: DEFAULT_APP_RANDOM_DRAW_CAP,
        }
    }

    fn scenario_def_from_components_with_app_random_draw_cap(
        &self,
        plan: &Plan,
        properties: &Properties,
        seed: Seed,
        app_random_draw_cap: u64,
    ) -> ScenarioDef {
        let material = scenario_world_plan_properties_seed_app_random_cap_material(
            self,
            plan,
            properties,
            seed,
            app_random_draw_cap,
        );
        ScenarioDef {
            id: ContentHash::from_canonical_material(
                "crucible.model.world-plan-properties-seed-scenario.v1",
                &material,
            ),
            seed,
            app_random_draw_cap,
        }
    }
}

/// Reusable node settings for code-first scenario authoring.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub struct NodeTemplate {
    arch: VmArchitecture,
    memory_mib: u32,
    cmdline: String,
    ready_point: ReadyPoint,
    white_box: WhiteBoxPolicy,
    smp_vcpus: u16,
    icount_shift: u8,
    kernel: Option<ContentAddressedBlobRef>,
    root_image: Option<ContentAddressedBlobRef>,
    initrd: Option<ContentAddressedBlobRef>,
}

impl NodeTemplate {
    /// The default virtual-machine architecture for a world node.
    pub const DEFAULT_ARCH: VmArchitecture = VmArchitecture::X86_64;
    /// The default virtual-machine memory size in MiB.
    pub const DEFAULT_MEMORY_MIB: u32 = 512;
    /// The default fixed vCPU count for a world node.
    pub const DEFAULT_SMP_VCPUS: u16 = 1;
    /// The default fixed icount shift for a world node.
    pub const DEFAULT_ICOUNT_SHIFT: u8 = 0;

    /// Builds a node template with the supplied ready point and white-box disabled.
    #[must_use]
    pub fn new(ready_point: ReadyPoint) -> Self {
        Self {
            arch: Self::DEFAULT_ARCH,
            memory_mib: Self::DEFAULT_MEMORY_MIB,
            cmdline: String::new(),
            ready_point,
            white_box: WhiteBoxPolicy::Disabled,
            smp_vcpus: Self::DEFAULT_SMP_VCPUS,
            icount_shift: Self::DEFAULT_ICOUNT_SHIFT,
            kernel: None,
            root_image: None,
            initrd: None,
        }
    }

    /// Builds a template for a fixed-instruction ready point.
    #[must_use]
    pub fn fixed_icount(icount: Icount) -> Self {
        Self::new(ReadyPoint::FixedIcount { icount })
    }

    /// Builds a template for a network-idle ready point.
    #[must_use]
    pub fn network_idle(window: SimDuration) -> Self {
        Self::new(ReadyPoint::NetworkIdle { window })
    }

    /// Builds a template for a console-marker ready point.
    #[must_use]
    pub fn console_marker(marker: impl Into<String>) -> Self {
        Self::new(ReadyPoint::ConsoleMarker {
            marker: marker.into(),
        })
    }

    /// Builds a template for an agent-signal ready point with white-box opt-in.
    #[must_use]
    pub fn agent_signal() -> Self {
        Self {
            arch: Self::DEFAULT_ARCH,
            memory_mib: Self::DEFAULT_MEMORY_MIB,
            cmdline: String::new(),
            ready_point: ReadyPoint::AgentSignal,
            white_box: WhiteBoxPolicy::Enabled,
            smp_vcpus: Self::DEFAULT_SMP_VCPUS,
            icount_shift: Self::DEFAULT_ICOUNT_SHIFT,
            kernel: None,
            root_image: None,
            initrd: None,
        }
    }

    /// Builds a node template by copying another world node's settings.
    #[must_use]
    pub fn from_world_node(node: &WorldNode) -> Self {
        Self {
            arch: node.arch,
            memory_mib: node.memory_mib,
            cmdline: node.cmdline.clone(),
            ready_point: node.ready_point.clone(),
            white_box: node.white_box,
            smp_vcpus: node.smp_vcpus,
            icount_shift: node.icount_shift,
            kernel: node.kernel,
            root_image: node.root_image,
            initrd: node.initrd,
        }
    }

    /// Replaces the template ready point.
    #[must_use]
    pub fn ready_point(mut self, ready_point: ReadyPoint) -> Self {
        self.ready_point = ready_point;
        self
    }

    /// Replaces the template white-box policy.
    #[must_use]
    pub fn white_box(mut self, white_box: WhiteBoxPolicy) -> Self {
        self.white_box = white_box;
        self
    }

    /// Replaces the virtual-machine architecture.
    #[must_use]
    pub fn arch(mut self, arch: VmArchitecture) -> Self {
        self.arch = arch;
        self
    }

    /// Replaces the virtual-machine memory size in MiB.
    #[must_use]
    pub fn memory_mib(mut self, memory_mib: u32) -> Self {
        self.memory_mib = memory_mib;
        self
    }

    /// Replaces the guest kernel command line.
    #[must_use]
    pub fn cmdline(mut self, cmdline: impl Into<String>) -> Self {
        self.cmdline = cmdline.into();
        self
    }

    /// Selects a supported in-guest workload binary by scenario parameter.
    ///
    /// The selected workload is encoded as `crucible.workload=...` in the guest
    /// command line, which is already part of the content-addressed world and
    /// scenario identity. This helper does not install an agent or create a
    /// host-side application traffic source.
    #[must_use]
    pub fn guest_workload(mut self, workload: GuestWorkloadBinary) -> Self {
        self.cmdline = workload.selected_cmdline(&self.cmdline);
        self
    }

    /// Delivers an explicit workload seed through black-box scenario config.
    ///
    /// The seed is encoded as `wseed=0x...` in the guest command line, which is
    /// already part of the content-addressed world and scenario identity. This
    /// path does not require [`WhiteBoxPolicy::Enabled`].
    #[must_use]
    pub fn guest_workload_seed(mut self, seed: GuestWorkloadSeed) -> Self {
        self.cmdline = seed.selected_cmdline(&self.cmdline);
        self
    }

    /// Delivers a scalar workload parameter through black-box scenario config.
    ///
    /// The parameter is encoded as a stable `key=value` token in the guest
    /// command line, which is already part of the content-addressed world and
    /// scenario identity.
    #[must_use]
    pub fn guest_workload_scalar_parameter(
        mut self,
        parameter: &GuestWorkloadScalarParameter,
    ) -> Self {
        self.cmdline = parameter.selected_cmdline(&self.cmdline);
        self
    }

    /// Delivers a structured workload config tree through immutable scenario config.
    ///
    /// The tree reference is encoded as `wcfg=...` in the guest command line. A
    /// rootfs-backed config also selects the same content-addressed blob as the
    /// node's read-only root image, so the structured config is represented in
    /// both the delivery surface and the world's canonical material.
    #[must_use]
    pub fn guest_workload_config_tree(mut self, config: &GuestWorkloadConfigTreeRef) -> Self {
        self.cmdline = config.selected_cmdline(&self.cmdline);
        if config.delivery() == GuestWorkloadConfigTreeDelivery::ReadOnlyRootfs {
            self.root_image = Some(config.export());
        }
        self
    }

    /// Selects an in-guest load pattern by scenario parameter.
    ///
    /// The pattern is encoded as `load_pattern=...` in the guest command line,
    /// keeping the load shape in the content-addressed world instead of a
    /// host-side load-generation subsystem.
    #[must_use]
    pub fn guest_workload_pattern(mut self, pattern: GuestWorkloadPattern) -> Self {
        self.cmdline = pattern.selected_cmdline(&self.cmdline);
        self
    }

    /// Selects the spike-pattern mode by scenario parameter.
    ///
    /// The mode is encoded as `spike_mode=...` in the guest command line and is
    /// consumed by the selected in-guest workload.
    #[must_use]
    pub fn guest_workload_spike_mode(mut self, mode: GuestWorkloadSpikeMode) -> Self {
        self.cmdline = mode.selected_cmdline(&self.cmdline);
        self
    }

    /// Selects the time source for a time-varying load pattern by scenario parameter.
    ///
    /// The only supported source is virtual time. The source is encoded as
    /// `load_time_source=virtual_time` in the guest command line.
    #[must_use]
    pub fn guest_workload_time_source(mut self, source: GuestWorkloadTimeSource) -> Self {
        self.cmdline = source.selected_cmdline(&self.cmdline);
        self
    }

    /// Replaces the fixed vCPU count.
    #[must_use]
    pub fn smp_vcpus(mut self, smp_vcpus: u16) -> Self {
        self.smp_vcpus = smp_vcpus;
        self
    }

    /// Replaces the fixed icount shift.
    #[must_use]
    pub fn icount_shift(mut self, icount_shift: u8) -> Self {
        self.icount_shift = icount_shift;
        self
    }

    /// Replaces the template kernel blob reference.
    #[must_use]
    pub fn kernel(mut self, kernel: ContentAddressedBlobRef) -> Self {
        self.kernel = Some(kernel);
        self
    }

    /// Replaces the template root-image blob reference.
    #[must_use]
    pub fn root_image(mut self, root_image: ContentAddressedBlobRef) -> Self {
        self.root_image = Some(root_image);
        self
    }

    /// Replaces the template initrd blob reference.
    #[must_use]
    pub fn initrd(mut self, initrd: ContentAddressedBlobRef) -> Self {
        self.initrd = Some(initrd);
        self
    }

    fn instantiate(&self, id: NodeId) -> WorldNode {
        WorldNode {
            id,
            arch: self.arch,
            memory_mib: self.memory_mib,
            cmdline: self.cmdline.clone(),
            ready_point: self.ready_point.clone(),
            white_box: self.white_box,
            smp_vcpus: self.smp_vcpus,
            icount_shift: self.icount_shift,
            kernel: self.kernel,
            root_image: self.root_image,
            initrd: self.initrd,
        }
    }
}

impl From<WorldNode> for NodeTemplate {
    fn from(node: WorldNode) -> Self {
        Self::from_world_node(&node)
    }
}

/// Code-first scenario authoring surface for the four orthogonal scenario layers.
#[derive(Clone, Debug, Default)]
pub struct ScenarioBuilder {
    nodes: Vec<PendingScenarioNode>,
    links: Vec<PendingScenarioLink>,
    plan: Option<Plan>,
    plan_entries: Vec<PlanEntry>,
    properties: Option<Properties>,
    assertions: Vec<AssertionDef>,
    seed: Seed,
}

#[derive(Clone, Debug, PartialEq, Eq, Hash)]
enum PendingScenarioNode {
    Concrete(WorldNode),
    Like { id: NodeId, template: NodeId },
}

#[derive(Clone, Debug, PartialEq, Eq, Hash)]
enum PendingScenarioLink {
    Default {
        left: NodeId,
        right: NodeId,
    },
    Transport {
        left: NodeId,
        right: NodeId,
        latency: SimDuration,
        jitter: SimDuration,
        loss: LinkLossProbability,
        bandwidth_bps: Option<u64>,
    },
    Concrete(LinkDef),
}

impl ScenarioBuilder {
    /// Starts an empty scenario builder with empty plan/properties and default seed.
    #[must_use]
    pub fn new() -> Self {
        Self::default()
    }

    /// Copies a complete world into the builder's world layer.
    #[must_use]
    pub fn world(mut self, world: &World) -> Self {
        self.nodes.extend(
            world
                .nodes()
                .iter()
                .cloned()
                .map(PendingScenarioNode::Concrete),
        );
        self.links.extend(
            world
                .links()
                .iter()
                .cloned()
                .map(PendingScenarioLink::Concrete),
        );
        self
    }

    /// Adds a concrete node from a reusable node template.
    #[must_use]
    pub fn node(mut self, name: impl Into<String>, template: NodeTemplate) -> Self {
        let id = NodeId { name: name.into() };
        self.nodes
            .push(PendingScenarioNode::Concrete(template.instantiate(id)));
        self
    }

    /// Adds a node by copying another declared node's template settings at build time.
    #[must_use]
    pub fn node_like(mut self, name: impl Into<String>, template: impl Into<String>) -> Self {
        self.nodes.push(PendingScenarioNode::Like {
            id: NodeId { name: name.into() },
            template: NodeId {
                name: template.into(),
            },
        });
        self
    }

    /// Adds a default logical world link between two node names.
    #[must_use]
    pub fn link(mut self, left: impl Into<String>, right: impl Into<String>) -> Self {
        self.links.push(PendingScenarioLink::Default {
            left: NodeId { name: left.into() },
            right: NodeId { name: right.into() },
        });
        self
    }

    /// Adds a logical world link with explicit transport characteristics.
    #[must_use]
    pub fn link_with_transport(
        mut self,
        left: impl Into<String>,
        right: impl Into<String>,
        latency: SimDuration,
        jitter: SimDuration,
        loss: LinkLossProbability,
        bandwidth_bps: Option<u64>,
    ) -> Self {
        self.links.push(PendingScenarioLink::Transport {
            left: NodeId { name: left.into() },
            right: NodeId { name: right.into() },
            latency,
            jitter,
            loss,
            bandwidth_bps,
        });
        self
    }

    /// Adds an already-constructed logical world link.
    #[must_use]
    pub fn link_def(mut self, link: LinkDef) -> Self {
        self.links.push(PendingScenarioLink::Concrete(link));
        self
    }

    /// Sets the complete plan layer.
    #[must_use]
    pub fn plan(mut self, plan: Plan) -> Self {
        self.plan = Some(plan);
        self.plan_entries.clear();
        self
    }

    /// Adds one plan entry to the plan layer.
    #[must_use]
    pub fn plan_entry(mut self, entry: PlanEntry) -> Self {
        self.plan = None;
        self.plan_entries.push(entry);
        self
    }

    /// Sets the complete properties layer.
    #[must_use]
    pub fn properties(mut self, properties: Properties) -> Self {
        self.properties = Some(properties);
        self.assertions.clear();
        self
    }

    /// Adds one assertion to the properties layer.
    #[must_use]
    pub fn property(mut self, assertion: AssertionDef) -> Self {
        self.properties = None;
        self.assertions.push(assertion);
        self
    }

    /// Sets the scenario root entropy.
    #[must_use]
    pub fn seed(mut self, seed: Seed) -> Self {
        self.seed = seed;
        self
    }

    /// Builds, validates, canonicalizes, and content-addresses the scenario.
    ///
    /// # Errors
    ///
    /// Returns world validation errors for invalid node/link topology, plan
    /// validation errors when plan entries cannot layer over the static world,
    /// property validation errors when assertions reference undeclared nodes or
    /// malformed compound predicates, or
    /// [`EngineError::ScenarioBuilderUnknownNodeTemplate`] when a `node_like`
    /// entry names no concrete node template.
    pub fn build(self) -> Result<ScenarioDef, EngineError> {
        let world = World::from_nodes_and_links(self.build_nodes()?, self.build_links()?)?;
        let plan = self.build_plan(&world)?;
        let properties = self.build_properties(&world)?;
        world.scenario_def_with_plan_properties_and_seed(&plan, &properties, self.seed)
    }

    fn build_nodes(&self) -> Result<Vec<WorldNode>, EngineError> {
        let mut templates = BTreeMap::new();
        let mut nodes = Vec::with_capacity(self.nodes.len());

        for pending in &self.nodes {
            if let PendingScenarioNode::Concrete(node) = pending {
                templates.insert(node.id.clone(), NodeTemplate::from_world_node(node));
                nodes.push(node.clone());
            }
        }

        for pending in &self.nodes {
            if let PendingScenarioNode::Like { id, template } = pending {
                let node_template = templates.get(template).ok_or_else(|| {
                    EngineError::ScenarioBuilderUnknownNodeTemplate {
                        node: id.clone(),
                        template: template.clone(),
                    }
                })?;
                nodes.push(node_template.instantiate(id.clone()));
            }
        }

        Ok(nodes)
    }

    fn build_links(&self) -> Result<Vec<LinkDef>, EngineError> {
        self.links
            .iter()
            .map(|pending| match pending {
                PendingScenarioLink::Default { left, right } => {
                    LinkDef::new(left.clone(), right.clone())
                }
                PendingScenarioLink::Transport {
                    left,
                    right,
                    latency,
                    jitter,
                    loss,
                    bandwidth_bps,
                } => LinkDef::with_transport(
                    left.clone(),
                    right.clone(),
                    *latency,
                    *jitter,
                    *loss,
                    *bandwidth_bps,
                ),
                PendingScenarioLink::Concrete(link) => Ok(link.clone()),
            })
            .collect()
    }

    fn build_plan(&self, world: &World) -> Result<Plan, EngineError> {
        if let Some(plan) = &self.plan {
            return Ok(plan.clone());
        }

        if self.plan_entries.is_empty() {
            Ok(Plan::empty())
        } else {
            Plan::from_entries_for_world(world, self.plan_entries.clone())
        }
    }

    fn build_properties(&self, world: &World) -> Result<Properties, EngineError> {
        if let Some(properties) = &self.properties {
            properties.validate_for_world(world)?;
            return Ok(properties.clone());
        }

        if self.assertions.is_empty() {
            Ok(Properties::empty())
        } else {
            Properties::from_assertions_for_world(world, self.assertions.clone())
        }
    }
}

/// A deterministic fixed-point fault density for [`ScenarioFamily`] generation.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct FaultDensity {
    millionths: u32,
}

impl FaultDensity {
    /// The density that generates no family faults.
    pub const ZERO: Self = Self { millionths: 0 };

    /// The density that selects every deterministic fault candidate.
    pub const ONE: Self = Self {
        millionths: MAX_FAMILY_FAULT_DENSITY_MILLIONTHS,
    };

    /// Builds a density from millionths in the closed range `[0, 1_000_000]`.
    ///
    /// `0` means no generated faults, and `1_000_000` means every candidate fault
    /// for the generated topology. The fixed-point representation avoids
    /// floating-point ambiguity in family parameter points.
    ///
    /// # Errors
    ///
    /// Returns [`EngineError::FaultDensityOutOfRange`] when `millionths` is greater
    /// than `1_000_000`.
    pub fn from_millionths(millionths: u32) -> Result<Self, EngineError> {
        if millionths > MAX_FAMILY_FAULT_DENSITY_MILLIONTHS {
            return Err(EngineError::FaultDensityOutOfRange {
                millionths,
                maximum: MAX_FAMILY_FAULT_DENSITY_MILLIONTHS,
            });
        }

        Ok(Self { millionths })
    }

    /// Returns this density as millionths in the closed range `[0, 1_000_000]`.
    #[must_use]
    pub fn millionths(self) -> u32 {
        self.millionths
    }

    fn scaled_count(self, candidates: usize) -> usize {
        if self.millionths == 0 || candidates == 0 {
            return 0;
        }

        let numerator = (candidates as u128) * u128::from(self.millionths);
        let denominator = u128::from(MAX_FAMILY_FAULT_DENSITY_MILLIONTHS);
        numerator.div_ceil(denominator) as usize
    }
}

/// Inclusive finite range of family fault-density values.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct FaultDensityRange {
    min: FaultDensity,
    max: FaultDensity,
}

impl FaultDensityRange {
    /// Builds an inclusive fault-density range.
    ///
    /// # Errors
    ///
    /// Returns [`EngineError::ScenarioFamilyInvalidSpace`] when `min > max`.
    pub fn new(min: FaultDensity, max: FaultDensity) -> Result<Self, EngineError> {
        if min > max {
            return Err(EngineError::ScenarioFamilyInvalidSpace {
                reason: "fault density range minimum exceeds maximum",
            });
        }

        Ok(Self { min, max })
    }

    /// Returns the minimum density in the range.
    #[must_use]
    pub fn min(self) -> FaultDensity {
        self.min
    }

    /// Returns the maximum density in the range.
    #[must_use]
    pub fn max(self) -> FaultDensity {
        self.max
    }

    /// Returns whether `density` is in this range.
    #[must_use]
    pub fn contains(self, density: FaultDensity) -> bool {
        self.min <= density && density <= self.max
    }

    fn len(self) -> u64 {
        u64::from(self.max.millionths - self.min.millionths) + 1
    }

    fn at(self, index: u64) -> Result<FaultDensity, EngineError> {
        if index >= self.len() {
            return Err(EngineError::ScenarioFamilyParameterOutOfSpace {
                parameter: "fault_density",
            });
        }
        FaultDensity::from_millionths(self.min.millionths + index as u32)
    }
}

/// Inclusive finite range of generated family topology sizes.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct TopologySizeRange {
    min: u32,
    max: u32,
}

impl TopologySizeRange {
    /// Builds an inclusive topology-size range.
    ///
    /// # Errors
    ///
    /// Returns [`EngineError::ScenarioFamilyInvalidSpace`] when the range is empty,
    /// starts at zero, or exceeds the implementation's bounded generation limit.
    pub fn new(min: u32, max: u32) -> Result<Self, EngineError> {
        if min == 0 {
            return Err(EngineError::ScenarioFamilyInvalidSpace {
                reason: "topology size range must start above zero",
            });
        }
        if min > max {
            return Err(EngineError::ScenarioFamilyInvalidSpace {
                reason: "topology size range minimum exceeds maximum",
            });
        }
        if max > MAX_SCENARIO_FAMILY_TOPOLOGY_SIZE {
            return Err(EngineError::ScenarioFamilyInvalidSpace {
                reason: "topology size range exceeds family generation limit",
            });
        }

        Ok(Self { min, max })
    }

    /// Returns the minimum generated node count.
    #[must_use]
    pub fn min(self) -> u32 {
        self.min
    }

    /// Returns the maximum generated node count.
    #[must_use]
    pub fn max(self) -> u32 {
        self.max
    }

    /// Returns whether `size` is in this range.
    #[must_use]
    pub fn contains(self, size: u32) -> bool {
        self.min <= size && size <= self.max
    }

    fn len(self) -> u64 {
        u64::from(self.max - self.min) + 1
    }

    fn at(self, index: u64) -> Result<u32, EngineError> {
        if index >= self.len() {
            return Err(EngineError::ScenarioFamilyParameterOutOfSpace {
                parameter: "topology_size",
            });
        }
        Ok(self.min + index as u32)
    }
}

/// Topology shape axis for [`ScenarioFamily`] generation.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum TopologyShape {
    /// Connect each node to its successor, wrapping the last node to the first.
    Ring,
    /// Connect every non-center node to `node-0`.
    Star,
    /// Connect every node pair.
    Mesh,
    /// Build a deterministic seed-derived connected graph.
    Random,
}

/// Finite seed axis for [`ScenarioFamily`] generation.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub struct SeedSpace {
    kind: SeedSpaceKind,
}

#[derive(Clone, Debug, PartialEq, Eq, Hash)]
enum SeedSpaceKind {
    Explicit(Vec<Seed>),
    Generated { meta_seed: Seed, count: u32 },
}

impl SeedSpace {
    /// Builds a seed space from an explicit set of seeds.
    ///
    /// The stored set is sorted for deterministic sampling.
    ///
    /// # Errors
    ///
    /// Returns [`EngineError::ScenarioFamilyInvalidSpace`] when `seeds` is empty,
    /// too large, or contains duplicates.
    pub fn explicit(seeds: Vec<Seed>) -> Result<Self, EngineError> {
        if seeds.is_empty() {
            return Err(EngineError::ScenarioFamilyInvalidSpace {
                reason: "seed space must not be empty",
            });
        }
        if seeds.len() > MAX_SCENARIO_FAMILY_SEEDS as usize {
            return Err(EngineError::ScenarioFamilyInvalidSpace {
                reason: "seed space exceeds family generation limit",
            });
        }

        let mut seeds = seeds;
        seeds.sort();
        if seeds.windows(2).any(|window| window[0] == window[1]) {
            return Err(EngineError::ScenarioFamilyInvalidSpace {
                reason: "seed space contains duplicate seeds",
            });
        }

        Ok(Self {
            kind: SeedSpaceKind::Explicit(seeds),
        })
    }

    /// Builds a finite seed space deterministically derived from `meta_seed`.
    ///
    /// # Errors
    ///
    /// Returns [`EngineError::ScenarioFamilyInvalidSpace`] when `count` is zero or
    /// exceeds the implementation's bounded generation limit.
    pub fn generated(meta_seed: Seed, count: u32) -> Result<Self, EngineError> {
        if count == 0 {
            return Err(EngineError::ScenarioFamilyInvalidSpace {
                reason: "generated seed space must not be empty",
            });
        }
        if count > MAX_SCENARIO_FAMILY_SEEDS {
            return Err(EngineError::ScenarioFamilyInvalidSpace {
                reason: "seed space exceeds family generation limit",
            });
        }

        Ok(Self {
            kind: SeedSpaceKind::Generated { meta_seed, count },
        })
    }

    /// Returns the number of seeds in this finite seed space.
    #[must_use]
    pub fn len(&self) -> u64 {
        match &self.kind {
            SeedSpaceKind::Explicit(seeds) => seeds.len() as u64,
            SeedSpaceKind::Generated { count, .. } => u64::from(*count),
        }
    }

    /// Returns whether this seed space is empty.
    #[must_use]
    pub fn is_empty(&self) -> bool {
        self.len() == 0
    }

    /// Returns the seed at `index`.
    ///
    /// # Errors
    ///
    /// Returns [`EngineError::ScenarioFamilyParameterOutOfSpace`] when `index` is
    /// outside this finite seed space.
    pub fn seed_at(&self, index: u64) -> Result<Seed, EngineError> {
        if index >= self.len() {
            return Err(EngineError::ScenarioFamilyParameterOutOfSpace { parameter: "seed" });
        }

        match &self.kind {
            SeedSpaceKind::Explicit(seeds) => Ok(seeds[index as usize]),
            SeedSpaceKind::Generated { meta_seed, .. } => Ok(derive_family_seed(*meta_seed, index)),
        }
    }

    fn contains(&self, seed: Seed) -> bool {
        match &self.kind {
            SeedSpaceKind::Explicit(seeds) => seeds.binary_search(&seed).is_ok(),
            SeedSpaceKind::Generated { count, meta_seed } => {
                (0..u64::from(*count)).any(|index| derive_family_seed(*meta_seed, index) == seed)
            }
        }
    }
}

/// The deterministic parameter space a [`ScenarioFamily`] ranges over.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub struct FamilySpace {
    seeds: SeedSpace,
    fault_density: FaultDensityRange,
    topology_size: TopologySizeRange,
    topology_shapes: Vec<TopologyShape>,
}

impl FamilySpace {
    /// Builds a finite family parameter space.
    ///
    /// Shapes are sorted and deduplicated so sampling is deterministic regardless
    /// of authoring order.
    ///
    /// # Errors
    ///
    /// Returns [`EngineError::ScenarioFamilyInvalidSpace`] when `topology_shapes`
    /// is empty.
    pub fn new(
        seeds: SeedSpace,
        fault_density: FaultDensityRange,
        topology_size: TopologySizeRange,
        topology_shapes: Vec<TopologyShape>,
    ) -> Result<Self, EngineError> {
        if topology_shapes.is_empty() {
            return Err(EngineError::ScenarioFamilyInvalidSpace {
                reason: "topology shape set must not be empty",
            });
        }

        let mut topology_shapes = topology_shapes;
        topology_shapes.sort();
        topology_shapes.dedup();

        Ok(Self {
            seeds,
            fault_density,
            topology_size,
            topology_shapes,
        })
    }

    /// Returns this space's seed axis.
    #[must_use]
    pub fn seeds(&self) -> &SeedSpace {
        &self.seeds
    }

    /// Returns this space's fault-density axis.
    #[must_use]
    pub fn fault_density(&self) -> FaultDensityRange {
        self.fault_density
    }

    /// Returns this space's topology-size axis.
    #[must_use]
    pub fn topology_size(&self) -> TopologySizeRange {
        self.topology_size
    }

    /// Returns this space's canonical topology-shape axis.
    #[must_use]
    pub fn topology_shapes(&self) -> &[TopologyShape] {
        &self.topology_shapes
    }

    /// Returns whether `params` lies inside this space.
    #[must_use]
    pub fn contains(&self, params: FamilyParams) -> bool {
        self.seeds.contains(params.seed)
            && self.fault_density.contains(params.fault_density)
            && self.topology_size.contains(params.topology_size)
            && self
                .topology_shapes
                .binary_search(&params.topology_shape)
                .is_ok()
    }

    /// Returns the finite cardinality of this family space.
    ///
    /// # Errors
    ///
    /// Returns [`EngineError::ScenarioFamilyInvalidSpace`] if the finite space size
    /// overflows `u64`.
    pub fn cardinality(&self) -> Result<u64, EngineError> {
        let seed_count = self.seeds.len();
        let shape_count = self.topology_shapes.len() as u64;
        let size_count = self.topology_size.len();
        let density_count = self.fault_density.len();
        let total = seed_count
            .checked_mul(shape_count)
            .and_then(|count| count.checked_mul(size_count))
            .and_then(|count| count.checked_mul(density_count))
            .ok_or(EngineError::ScenarioFamilyInvalidSpace {
                reason: "family space cardinality overflows u64",
            })?;
        if total == 0 {
            return Err(EngineError::ScenarioFamilyInvalidSpace {
                reason: "family space must not be empty",
            });
        }

        Ok(total)
    }

    /// Deterministically samples one parameter point by cartesian index.
    ///
    /// The finite axes are traversed in seed, shape, size, then density order.
    /// Callers that want an unbounded fuzz counter should explicitly wrap by
    /// [`Self::cardinality`] so exhaustive enumeration can still reject an
    /// out-of-space index.
    ///
    /// # Errors
    ///
    /// Returns [`EngineError::ScenarioFamilyParameterOutOfSpace`] when `index` is
    /// greater than or equal to [`Self::cardinality`].
    pub fn sample(&self, index: u64) -> Result<FamilyParams, EngineError> {
        let total = self.cardinality()?;
        if index >= total {
            return Err(EngineError::ScenarioFamilyParameterOutOfSpace {
                parameter: "sample_index",
            });
        }

        let seed_count = self.seeds.len();
        let shape_count = self.topology_shapes.len() as u64;
        let size_count = self.topology_size.len();
        let density_count = self.fault_density.len();
        let mut index = index;
        let seed = self.seeds.seed_at(index % seed_count)?;
        index /= seed_count;
        let topology_shape = self.topology_shapes[(index % shape_count) as usize];
        index /= shape_count;
        let topology_size = self.topology_size.at(index % size_count)?;
        index /= size_count;
        let fault_density = self.fault_density.at(index % density_count)?;

        Ok(FamilyParams {
            seed,
            fault_density,
            topology_size,
            topology_shape,
        })
    }

    fn validate_params(&self, params: FamilyParams) -> Result<(), EngineError> {
        if !self.seeds.contains(params.seed) {
            return Err(EngineError::ScenarioFamilyParameterOutOfSpace { parameter: "seed" });
        }
        if !self.fault_density.contains(params.fault_density) {
            return Err(EngineError::ScenarioFamilyParameterOutOfSpace {
                parameter: "fault_density",
            });
        }
        if !self.topology_size.contains(params.topology_size) {
            return Err(EngineError::ScenarioFamilyParameterOutOfSpace {
                parameter: "topology_size",
            });
        }
        if self
            .topology_shapes
            .binary_search(&params.topology_shape)
            .is_err()
        {
            return Err(EngineError::ScenarioFamilyParameterOutOfSpace {
                parameter: "topology_shape",
            });
        }

        Ok(())
    }
}

/// One concrete point sampled from a [`ScenarioFamily`] parameter space.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct FamilyParams {
    /// Concrete root seed for the pinned scenario.
    pub seed: Seed,
    /// Concrete exact fault density used to generate the plan.
    pub fault_density: FaultDensity,
    /// Concrete generated node count.
    pub topology_size: u32,
    /// Concrete generated topology shape.
    pub topology_shape: TopologyShape,
}

/// Parametric generator over concrete, validated scenario definitions.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub struct ScenarioFamily {
    space: FamilySpace,
    node_template: NodeTemplate,
    assertions: Vec<AssertionDef>,
}

impl ScenarioFamily {
    /// Builds a scenario family from a parameter space and reusable node template.
    #[must_use]
    pub fn new(space: FamilySpace, node_template: NodeTemplate) -> Self {
        Self {
            space,
            node_template,
            assertions: Vec::new(),
        }
    }

    /// Returns the parameter space this family ranges over.
    #[must_use]
    pub fn space(&self) -> &FamilySpace {
        &self.space
    }

    /// Adds one assertion to every generated scenario's properties layer.
    #[must_use]
    pub fn property(mut self, assertion: AssertionDef) -> Self {
        self.assertions.push(assertion);
        self
    }

    /// Instantiates a concrete validated scenario at `params`.
    ///
    /// The returned [`PinnedScenario`] contains the concrete [`ScenarioDefForm`]
    /// used by execution and reproduction. It carries no reference back to this
    /// family, so callers can only run the pinned scenario definition.
    ///
    /// # Errors
    ///
    /// Returns [`EngineError::ScenarioFamilyParameterOutOfSpace`] when `params`
    /// does not lie in the family space, or the usual world/plan/properties
    /// validation errors if the generated scenario is invalid.
    pub fn instantiate(&self, params: FamilyParams) -> Result<PinnedScenario, EngineError> {
        self.space.validate_params(params)?;
        let world = self.build_world(params)?;
        let plan = self.build_plan(&world, params)?;
        let properties = Properties::from_assertions_for_world(&world, self.assertions.clone())?;
        let form = ScenarioDefForm::from_components(&world, &plan, &properties, params.seed)?;
        Ok(PinnedScenario { params, form })
    }

    /// Samples and instantiates one deterministic parameter point.
    ///
    /// # Errors
    ///
    /// Returns the same errors as [`FamilySpace::sample`] or [`Self::instantiate`].
    pub fn instantiate_sample(&self, index: u64) -> Result<PinnedScenario, EngineError> {
        let params = self.space.sample(index)?;
        self.instantiate(params)
    }

    /// Samples and mutates concrete scenarios using event-log coverage feedback.
    ///
    /// Each iteration chooses one family parameter point, pins that point to a
    /// concrete [`ScenarioDef`], and appends a schedule mutation encoded as
    /// [`Decision::Override`]. Coverage influences only which deterministic
    /// samples are explored and how the returned candidates are ordered; it never
    /// changes the reduced execution semantics of a candidate.
    ///
    /// # Errors
    ///
    /// Returns [`EngineError::ScenarioFamilyInvalidSpace`] when the family space
    /// cannot be counted, [`EngineError::ScenarioFamilyParameterOutOfSpace`] when
    /// a sampled point is invalid, or any validation error from
    /// [`Self::instantiate`] or [`try_step`].
    pub fn fuzz_coverage_guided(
        &self,
        config: CoverageGuidedFuzzConfig,
        feedback: &[EventLogCoverageFeedback],
    ) -> Result<CoverageGuidedFuzzRun, EngineError> {
        run_coverage_guided_fuzz(self, config, feedback)
    }

    /// Runs coverage-guided fuzzing with a durable content-addressed corpus.
    ///
    /// The corpus stores every retained input as a self-contained
    /// [`ReproductionArtifact`] in `store`. Admission is coverage-driven: a
    /// candidate is retained only when its coverage fingerprint has no existing
    /// corpus owner. Rejected duplicate coverage is reported as deterministic
    /// subsumption pruning rather than stored as a corpus entry.
    ///
    /// # Errors
    ///
    /// Returns [`CoverageGuidedCorpusError::Engine`] when sampling, mutation,
    /// artifact capture, or replay validation fails. Returns
    /// [`CoverageGuidedCorpusError::Store`] when `store` cannot persist an
    /// admitted reproduction artifact.
    pub fn fuzz_coverage_guided_corpus<S>(
        &self,
        store: &S,
        config: CoverageGuidedFuzzConfig,
        corpus_config: CoverageGuidedCorpusConfig,
        feedback: &[EventLogCoverageFeedback],
    ) -> Result<CoverageGuidedCorpusRun, CoverageGuidedCorpusError>
    where
        S: DagStore + ?Sized,
    {
        run_coverage_guided_fuzz_corpus(self, store, config, corpus_config, feedback)
    }

    fn build_world(&self, params: FamilyParams) -> Result<World, EngineError> {
        let nodes = (0..params.topology_size)
            .map(|index| self.node_template.instantiate(family_node_id(index)))
            .collect::<Vec<_>>();
        let links = family_links(params)?;
        World::from_nodes_and_links(nodes, links)
    }

    fn build_plan(&self, world: &World, params: FamilyParams) -> Result<Plan, EngineError> {
        let candidates = family_fault_candidates(world);
        let fault_count = params.fault_density.scaled_count(candidates.len());
        let mut entries = Vec::with_capacity(fault_count.saturating_mul(2));
        for (index, candidate) in candidates.into_iter().take(fault_count).enumerate() {
            let activate_at = VirtualTime {
                ticks: FAMILY_FAULT_STEP_TICKS
                    .checked_mul(index as u64 + 1)
                    .ok_or(EngineError::ScenarioFamilyInvalidSpace {
                        reason: "generated family fault time overflows u64",
                    })?,
            };
            let heal_at = VirtualTime {
                ticks: activate_at
                    .ticks
                    .checked_add(FAMILY_FAULT_HEAL_DELAY_TICKS)
                    .ok_or(EngineError::ScenarioFamilyInvalidSpace {
                        reason: "generated family heal time overflows u64",
                    })?,
            };
            let tag = FaultTag::from_name(format!("family-fault-{index}"));
            entries.push(PlanEntry::Activate {
                at: activate_at,
                tag: tag.clone(),
                fault: candidate.into_fault(),
            });
            entries.push(PlanEntry::Heal { at: heal_at, tag });
        }

        Plan::from_entries_for_world(world, entries)
    }
}

/// A concrete scenario pinned from a [`ScenarioFamily`] parameter point.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub struct PinnedScenario {
    params: FamilyParams,
    form: ScenarioDefForm,
}

impl PinnedScenario {
    /// Returns the family parameters that produced this pinned instance.
    #[must_use]
    pub fn params(&self) -> FamilyParams {
        self.params
    }

    /// Returns the materialized concrete scenario form.
    #[must_use]
    pub fn form(&self) -> &ScenarioDefForm {
        &self.form
    }

    /// Consumes this pinned instance and returns its concrete scenario form.
    #[must_use]
    pub fn into_form(self) -> ScenarioDefForm {
        self.form
    }

    /// Reconstructs the concrete scenario definition used by execution.
    #[must_use]
    pub fn scenario_def(&self) -> ScenarioDef {
        self.form.scenario_def()
    }

    /// Builds the genesis execution configuration while retaining the concrete form.
    #[must_use]
    pub fn genesis_configuration(&self) -> PinnedConfiguration {
        PinnedConfiguration {
            scenario: self.form.clone(),
            configuration: Configuration::genesis(self.scenario_def()),
        }
    }

    /// Returns the concrete scenario id.
    #[must_use]
    pub fn id(&self) -> ContentHash {
        self.form.id()
    }
}

/// A run configuration pinned to a concrete materialized scenario form.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub struct PinnedConfiguration {
    scenario: ScenarioDefForm,
    configuration: Configuration,
}

impl PinnedConfiguration {
    /// Returns the concrete materialized scenario form for reproduction.
    #[must_use]
    pub fn scenario_form(&self) -> &ScenarioDefForm {
        &self.scenario
    }

    /// Returns the executable configuration handle for the pinned scenario.
    #[must_use]
    pub fn configuration(&self) -> &Configuration {
        &self.configuration
    }

    /// Consumes this pinned configuration into its concrete parts.
    #[must_use]
    pub fn into_parts(self) -> (ScenarioDefForm, Configuration) {
        (self.scenario, self.configuration)
    }
}

/// A self-contained `(seed, scenario, schedule)` reproduction bundle.
///
/// The seed is not stored as a drifting side channel: it is the embedded
/// [`ScenarioDefForm`]'s own seed. The artifact carries only the complete
/// validated scenario form and recorded schedule, so its identity is exactly the
/// RFC tuple `(seed, scenario, schedule)` without a parent family or host path.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub struct ReproductionArtifact {
    id: ContentHash,
    scenario: ScenarioDefForm,
    schedule: Schedule,
}

impl ReproductionArtifact {
    /// Captures an artifact by reducing `schedule` from `scenario`.
    ///
    /// # Errors
    ///
    /// Returns [`EngineError`] if the reduction function rejects the supplied
    /// scenario/schedule pair.
    pub fn capture(scenario: &ScenarioDefForm, schedule: &Schedule) -> Result<Self, EngineError> {
        let artifact = Self::from_recorded_parts(scenario.clone(), schedule.clone());
        let _ = artifact.replay()?;
        Ok(artifact)
    }

    /// Captures an artifact from an executable pinned configuration.
    ///
    /// # Errors
    ///
    /// Returns [`EngineError`] if replaying the pinned configuration's scenario
    /// and schedule cannot derive a reduced state.
    pub fn from_pinned_configuration(pinned: &PinnedConfiguration) -> Result<Self, EngineError> {
        Self::capture(pinned.scenario_form(), &pinned.configuration().schedule)
    }

    /// Rebuilds an artifact from already-recorded self-contained parts.
    #[must_use]
    pub fn from_recorded_parts(scenario: ScenarioDefForm, schedule: Schedule) -> Self {
        let id =
            ContentHash::from_bytes(&reproduction_artifact_canonical_bytes(&scenario, &schedule));
        Self {
            id,
            scenario,
            schedule,
        }
    }

    /// Parses a compact canonical artifact representation.
    ///
    /// # Errors
    ///
    /// Returns [`EngineError::ScenarioSerialization`] for malformed artifact,
    /// scenario, or schedule bytes.
    pub fn from_compact_binary(bytes: &[u8]) -> Result<Self, EngineError> {
        let mut reader = ScenarioBinaryReader::new(bytes, REPRODUCTION_ARTIFACT_BINARY_MAGIC)?;
        let scenario_bytes = reader.read_binary_blob("reproduction-artifact.scenario")?;
        let schedule_bytes = reader.read_binary_blob("reproduction-artifact.schedule")?;
        reader.finish()?;

        let scenario = ScenarioDefForm::from_compact_binary(scenario_bytes)?;
        let schedule = Schedule::from_compact_binary(schedule_bytes)?;
        Ok(Self::from_recorded_parts(scenario, schedule))
    }

    /// Returns the BLAKE3 content address over this artifact's canonical bytes.
    #[must_use]
    pub fn id(&self) -> ContentHash {
        self.id
    }

    /// Returns the concrete serialized scenario form carried by this artifact.
    #[must_use]
    pub fn scenario_form(&self) -> &ScenarioDefForm {
        &self.scenario
    }

    /// Reconstructs the immutable scenario definition carried by this artifact.
    #[must_use]
    pub fn scenario_def(&self) -> ScenarioDef {
        self.scenario.scenario_def()
    }

    /// Returns the scenario definition's root seed.
    #[must_use]
    pub fn seed(&self) -> Seed {
        self.scenario.seed()
    }

    /// Returns the recorded schedule carried by this artifact.
    #[must_use]
    pub fn schedule(&self) -> &Schedule {
        &self.schedule
    }

    /// Returns the canonical byte serialization hashed by [`Self::id`].
    #[must_use]
    pub fn canonical_bytes(&self) -> Vec<u8> {
        reproduction_artifact_canonical_bytes(&self.scenario, &self.schedule)
    }

    /// Serializes this artifact as compact canonical bytes.
    #[must_use]
    pub fn to_compact_binary(&self) -> Vec<u8> {
        self.canonical_bytes()
    }

    /// Replays the artifact through the reduction oracle.
    ///
    /// # Errors
    ///
    /// Returns [`EngineError`] if the reduction function rejects the embedded
    /// scenario/schedule pair.
    pub fn replay(&self) -> Result<ReproductionReplay, EngineError> {
        let state = reduce(&self.scenario_def(), &self.schedule)?;
        Ok(ReproductionReplay {
            artifact: self.id,
            scenario: self.scenario.id(),
            schedule: self.schedule.content_hash(),
            state: state.id,
        })
    }

    /// Replays the artifact and compares the result with an external target state.
    ///
    /// # Errors
    ///
    /// Returns [`EngineError::ReproductionArtifactReplayMismatch`] when the
    /// embedded scenario and schedule reduce to a state other than `expected`.
    /// Returns other [`EngineError`] variants if the reduction itself fails.
    pub fn verify_replay(&self, expected: ContentHash) -> Result<ReproductionReplay, EngineError> {
        let replay = self.replay()?;
        if replay.state != expected {
            return Err(EngineError::ReproductionArtifactReplayMismatch {
                artifact: self.id,
                expected,
                actual: replay.state,
            });
        }
        Ok(replay)
    }

    /// Captures the event-log debug/fork metadata for this reproduction artifact.
    ///
    /// The returned value records the causal-subsequence digest and fork-point
    /// index, not the full event log. Replaying the artifact can therefore
    /// recompute the log and compare against this compact record.
    #[must_use]
    pub fn event_log_debug_artifact(
        &self,
        fork_point: EventLogOffset,
        entries: &[crate::scheduler::SchedulerEventLogEntry],
    ) -> ReproductionEventLogArtifact {
        self.event_log_debug_artifact_with_segments(fork_point, entries, Vec::new())
    }

    /// Captures event-log debug/fork metadata with shared-store segment keys.
    ///
    /// `shared_store_segments` are optional content-addressed event-log segment
    /// keys. They let a shared store fetch retained log bytes, but replay
    /// correctness still comes from recomputing the log from the embedded
    /// scenario and schedule.
    #[must_use]
    pub fn event_log_debug_artifact_with_segments<I>(
        &self,
        fork_point: EventLogOffset,
        entries: &[crate::scheduler::SchedulerEventLogEntry],
        shared_store_segments: I,
    ) -> ReproductionEventLogArtifact
    where
        I: IntoIterator<Item = ContentHash>,
    {
        let projection = crate::scheduler::event_log_causal_projection(entries);
        let coverage_fingerprint = coverage_fingerprint_from_event_log(entries);
        ReproductionEventLogArtifact::from_causal_projection(
            self.id,
            fork_point,
            projection.content_hash(),
            projection.canonical_bytes().len(),
            projection.len(),
            coverage_fingerprint,
            shared_store_segments,
        )
    }

    /// Replays the artifact and checks a reconstructed event log against metadata.
    ///
    /// # Errors
    ///
    /// Returns [`EngineError`] if replaying this artifact's scenario/schedule or
    /// reconstructing the replay log fails before comparison.
    pub fn verify_event_log_replay_with<F>(
        &self,
        event_log: &ReproductionEventLogArtifact,
        replay_log: F,
    ) -> Result<ReproductionEventLogReplay, EngineError>
    where
        F: FnOnce(
            &ReproductionArtifact,
            &ReproductionReplay,
        ) -> Result<Vec<crate::scheduler::SchedulerEventLogEntry>, EngineError>,
    {
        let reduction = self.replay()?;
        let reproduced_entries = replay_log(self, &reduction)?;
        let reproduced = crate::scheduler::event_log_causal_projection(&reproduced_entries);
        let reproduced_coverage_fingerprint =
            coverage_fingerprint_from_event_log(&reproduced_entries);
        Ok(ReproductionEventLogReplay {
            reduction,
            event_log_artifact: event_log.id(),
            artifact_matches: event_log.reproduction_artifact == self.id,
            fork_point: event_log.fork_point,
            expected_causal_subsequence: event_log.causal_subsequence,
            reproduced_causal_subsequence: reproduced.content_hash(),
            expected_causal_bytes: event_log.causal_subsequence_bytes,
            reproduced_causal_bytes: reproduced.canonical_bytes().len(),
            expected_causal_events: event_log.causal_subsequence_events,
            reproduced_causal_events: reproduced.len(),
            expected_coverage_fingerprint: event_log.coverage_fingerprint,
            reproduced_coverage_fingerprint,
            shared_store_segments: event_log.shared_store_segments.clone(),
        })
    }
}

/// Discovery path that produced an interesting finding.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum FindingDiscoveryPath {
    /// Finding was produced by an interactive fork/session operation.
    InteractiveFork,
    /// Finding was produced by state-space search.
    StateSpaceSearch,
    /// Finding was produced by coverage-guided fuzzing.
    CoverageGuidedFuzzing,
    /// Finding is a retained coverage-guided corpus entry.
    RetainedCorpusEntry,
}

/// Self-contained reproduction artifact attached to one interesting finding.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub struct FindingReproductionArtifact {
    /// Discovery path that produced the finding.
    pub discovery_path: FindingDiscoveryPath,
    /// Stable finding fingerprint supplied by the discovering oracle.
    pub finding_fingerprint: ContentHash,
    /// Content-addressed execution configuration captured by the artifact.
    pub configuration: ContentHash,
    /// Self-contained `(seed, scenario, schedule)` artifact.
    pub artifact: ReproductionArtifact,
    /// Replay evidence proving the artifact reduces without snapshots.
    pub replay: ReproductionReplay,
}

impl FindingReproductionArtifact {
    /// Captures a finding artifact from a pinned scenario form and configuration.
    ///
    /// # Errors
    ///
    /// Returns [`EngineError::ReproductionScenarioMismatch`] when `scenario` is
    /// not the concrete form for `configuration`. Returns other [`EngineError`]
    /// values when artifact capture or replay validation fails.
    pub fn capture(
        discovery_path: FindingDiscoveryPath,
        finding_fingerprint: ContentHash,
        scenario: &ScenarioDefForm,
        configuration: &Configuration,
    ) -> Result<Self, EngineError> {
        let scenario_def = scenario.scenario_def();
        if scenario_def.id != configuration.def.id {
            return Err(EngineError::ReproductionScenarioMismatch {
                expected: configuration.def.id,
                actual: scenario_def.id,
            });
        }
        let expected_state = reduce(&configuration.def, &configuration.schedule)?.id;
        let artifact = ReproductionArtifact::capture(scenario, &configuration.schedule)?;
        let replay = artifact.verify_replay(expected_state)?;
        Ok(Self {
            discovery_path,
            finding_fingerprint,
            configuration: configuration.id(),
            artifact,
            replay,
        })
    }

    /// Stores this finding's self-contained artifact bytes in `store`.
    ///
    /// # Errors
    ///
    /// Returns [`DagStoreError`] when `store` cannot persist the artifact bytes.
    pub fn store_artifact<S>(&self, store: &S) -> Result<ContentHash, DagStoreError>
    where
        S: DagStore + ?Sized,
    {
        store.put(&self.artifact.to_compact_binary())
    }

    /// Rebuilds a finding artifact from a stored self-contained artifact.
    ///
    /// # Errors
    ///
    /// Returns [`FindingReproductionArtifactError::Store`] when the store cannot
    /// read `artifact_key`. Returns [`FindingReproductionArtifactError::Engine`]
    /// when the stored artifact bytes are malformed or fail replay validation.
    pub fn load_from_store<S>(
        discovery_path: FindingDiscoveryPath,
        finding_fingerprint: ContentHash,
        store: &S,
        artifact_key: ContentHash,
    ) -> Result<Self, FindingReproductionArtifactError>
    where
        S: DagStore + ?Sized,
    {
        let bytes =
            store
                .get(&artifact_key)
                .map_err(|source| FindingReproductionArtifactError::Store {
                    operation: "get-finding-artifact",
                    source,
                })?;
        let artifact = ReproductionArtifact::from_compact_binary(&bytes).map_err(|source| {
            FindingReproductionArtifactError::Engine {
                operation: "decode-finding-artifact",
                source: Box::new(source),
            }
        })?;
        let replay =
            artifact
                .replay()
                .map_err(|source| FindingReproductionArtifactError::Engine {
                    operation: "replay-finding-artifact",
                    source: Box::new(source),
                })?;
        let configuration = Configuration {
            def: artifact.scenario_def(),
            schedule: artifact.schedule().clone(),
        };
        Ok(Self {
            discovery_path,
            finding_fingerprint,
            configuration: configuration.id(),
            artifact,
            replay,
        })
    }

    /// Shrinks this finding while preserving its failure fingerprint.
    ///
    /// The minimizer enumerates every shorter recorded schedule subsequence in
    /// deterministic shortest-first order, with seeded content-address tie-breaks.
    /// Every candidate is replayed as a self-contained artifact before
    /// `failure_fingerprint` is consulted, and the first preserving candidate is
    /// therefore the stable shortest artifact under the supplied failure oracle.
    ///
    /// # Errors
    ///
    /// Returns [`EngineError::ReplayTargetMismatch`] or
    /// [`EngineError::ReproductionArtifactReplayMismatch`] when this public value
    /// does not match its embedded artifact/replay evidence, or when the starting
    /// artifact does not reproduce this finding's fingerprint. Returns other
    /// [`EngineError`] values when candidate capture, replay validation, or the
    /// caller-supplied failure oracle fails.
    pub fn minimize<F>(
        &self,
        config: MinimizationConfig,
        mut failure_fingerprint: F,
    ) -> Result<MinimizationRun, EngineError>
    where
        F: FnMut(&FindingReproductionArtifact) -> Result<Option<ContentHash>, EngineError>,
    {
        let original = self.validated()?;
        let target = original.finding_fingerprint;
        let initial = failure_fingerprint(&original)?;
        if initial != Some(target) {
            return Err(EngineError::ReplayTargetMismatch {
                expected: target,
                actual: initial.unwrap_or_default(),
            });
        }

        let mut attempts = Vec::new();
        let mut minimized = original.clone();
        let candidates = minimization_candidates(
            config.seed,
            original.artifact.id(),
            original.artifact.schedule(),
        );

        for (sequence, candidate) in candidates.into_iter().enumerate() {
            let configuration = Configuration {
                def: original.artifact.scenario_def(),
                schedule: candidate.schedule,
            };
            let finding = FindingReproductionArtifact::capture(
                original.discovery_path,
                target,
                original.artifact.scenario_form(),
                &configuration,
            )?;
            let observed_fingerprint = failure_fingerprint(&finding)?;
            let accepted_candidate = observed_fingerprint == Some(target);
            attempts.push(MinimizationAttempt {
                sequence: sequence as u64,
                removed_indices: candidate.removed_indices,
                removed_decisions: candidate.removed_decisions,
                candidate_artifact: finding.artifact.id(),
                candidate_schedule: finding.artifact.schedule().content_hash(),
                replayed_state: finding.replay.state,
                observed_fingerprint,
                accepted: accepted_candidate,
            });

            if accepted_candidate {
                minimized = finding;
                break;
            }
        }

        Ok(MinimizationRun {
            seed: config.seed,
            target_fingerprint: target,
            original,
            minimized,
            attempts,
        })
    }

    fn validated(&self) -> Result<Self, EngineError> {
        let replay = self.artifact.replay()?;
        if replay != self.replay {
            return Err(EngineError::ReproductionArtifactReplayMismatch {
                artifact: self.artifact.id(),
                expected: self.replay.state,
                actual: replay.state,
            });
        }
        let configuration = Configuration {
            def: self.artifact.scenario_def(),
            schedule: self.artifact.schedule().clone(),
        };
        let configuration_id = configuration.id();
        if configuration_id != self.configuration {
            return Err(EngineError::ReplayTargetMismatch {
                expected: self.configuration,
                actual: configuration_id,
            });
        }
        Ok(Self {
            discovery_path: self.discovery_path,
            finding_fingerprint: self.finding_fingerprint,
            configuration: configuration_id,
            artifact: self.artifact.clone(),
            replay,
        })
    }
}

/// Closed failure discriminant carried by a triage signature.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum FailureKind {
    /// The recorded run contains a failed assertion or property violation.
    PropertyViolation,
    /// The recorded run diverged from deterministic replay and was localized by bisection.
    Divergence,
}

/// Stable property identity carried by a property-violation signature.
#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct FailurePropertyKey {
    /// Stable assertion or property identifier read from the violation record.
    pub id: AssertionId,
    /// Quantifier or guest marker flavor read from the violation record.
    pub quantifier: AssertionQuantifierKind,
}

/// First attributable point for one recorded failure.
#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct FailureFirstFailingPoint {
    /// Open-set event kind attached to the violation site or bisection point.
    pub event_kind: String,
    /// Scenario node that owns the failure site, when the record is node-local.
    pub faulting_node: Option<NodeId>,
}

/// Bucketed coverage class used by the first failure-signature model.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct FailureCoverageClass {
    /// Versioned bucketing algorithm used for this class.
    pub algorithm: &'static str,
    /// Coarse deterministic bucket derived from the coverage fingerprint.
    pub bucket: u16,
}

impl FailureCoverageClass {
    /// Builds a bucketed class from a deterministic coverage fingerprint.
    #[must_use]
    pub fn from_coverage_fingerprint(coverage_fingerprint: ContentHash) -> Self {
        Self {
            algorithm: FAILURE_COVERAGE_CLASS_ALGORITHM,
            bucket: u16::from_be_bytes([
                coverage_fingerprint.bytes[0],
                coverage_fingerprint.bytes[1],
            ]),
        }
    }
}

/// Closed failure-signature policy levels.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum SignaturePolicyLevel {
    /// Clusters by failure kind and stable property id.
    Coarse,
    /// Clusters by the everyday failure key used by default triage.
    #[default]
    Default,
    /// Adds the cone-scoped causal slice hash to separate code paths.
    Fine,
    /// Adds absolute icount and full causal-cone material for forensic runs.
    Exact,
}

/// Versioned selector for failure-signature key fields.
///
/// The policy is closed over the four RFC0010 levels and records the schema
/// version plus coverage-class bucketing algorithm in every key projection and
/// triage result identity.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct SignaturePolicy {
    level: SignaturePolicyLevel,
}

impl SignaturePolicy {
    /// Returns the coarse clustering policy.
    #[must_use]
    pub fn coarse() -> Self {
        Self {
            level: SignaturePolicyLevel::Coarse,
        }
    }

    /// Returns the default clustering policy.
    #[must_use]
    pub fn default_policy() -> Self {
        Self {
            level: SignaturePolicyLevel::Default,
        }
    }

    /// Returns the fine-grained clustering policy.
    #[must_use]
    pub fn fine() -> Self {
        Self {
            level: SignaturePolicyLevel::Fine,
        }
    }

    /// Returns the exact forensic clustering policy.
    #[must_use]
    pub fn exact() -> Self {
        Self {
            level: SignaturePolicyLevel::Exact,
        }
    }

    /// Returns the closed policy level.
    #[must_use]
    pub fn level(&self) -> SignaturePolicyLevel {
        self.level
    }

    /// Returns the versioned policy schema identifier.
    #[must_use]
    pub fn schema_version(&self) -> u16 {
        SIGNATURE_POLICY_SCHEMA_VERSION
    }

    /// Returns the fixed coverage-class bucketing algorithm selected by policy.
    #[must_use]
    pub fn coverage_class_algorithm(&self) -> &'static str {
        FAILURE_COVERAGE_CLASS_ALGORITHM
    }

    /// Returns whether this policy allows minimization merges.
    ///
    /// `exact` is forensic and must not minimize-merge.
    #[must_use]
    pub fn allows_minimize_merge(&self) -> bool {
        !matches!(self.level, SignaturePolicyLevel::Exact)
    }

    /// Returns whether the causal slice hash is a key field.
    #[must_use]
    pub fn keys_causal_slice_hash(&self) -> bool {
        matches!(
            self.level,
            SignaturePolicyLevel::Fine | SignaturePolicyLevel::Exact
        )
    }

    /// Returns whether absolute icount is a key field.
    #[must_use]
    pub fn keys_absolute_icount(&self) -> bool {
        matches!(self.level, SignaturePolicyLevel::Exact)
    }

    /// Projects `signature` into this policy's deterministic key.
    ///
    /// # Errors
    ///
    /// Returns [`EngineError::UnifiedOperationEvidenceMismatch`] if the
    /// signature's coverage bucket was built by a different algorithm, or if the
    /// exact policy is requested for a signature that does not retain full
    /// causal-cone material.
    pub fn signature_key(
        &self,
        signature: &FailureSignature,
    ) -> Result<FailureSignatureKey, EngineError> {
        if signature.coverage_class.algorithm != self.coverage_class_algorithm() {
            return Err(EngineError::UnifiedOperationEvidenceMismatch {
                operation: "failure-signature.policy",
                reason: "signature coverage class algorithm does not match policy",
            });
        }
        if self.level == SignaturePolicyLevel::Exact && signature.causal_cone.is_none() {
            return Err(EngineError::UnifiedOperationEvidenceMismatch {
                operation: "failure-signature.policy",
                reason: "exact policy requires full causal cone material",
            });
        }
        Ok(FailureSignatureKey {
            policy: *self,
            canonical_material: failure_signature_key_material(signature, *self),
        })
    }

    /// Returns the canonical policy material included in result identities.
    #[must_use]
    pub fn canonical_material(&self) -> String {
        failure_signature_policy_material(*self)
    }

    /// Returns the content address of this policy selector.
    #[must_use]
    pub fn content_hash(&self) -> ContentHash {
        ContentHash::from_canonical_material(
            FAILURE_SIGNATURE_KEY_DOMAIN,
            &self.canonical_material(),
        )
    }
}

/// Deterministic projection of a signature under a [`SignaturePolicy`].
#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct FailureSignatureKey {
    policy: SignaturePolicy,
    canonical_material: String,
}

impl FailureSignatureKey {
    /// Returns the policy that selected this key's fields.
    #[must_use]
    pub fn policy(&self) -> SignaturePolicy {
        self.policy
    }

    /// Returns the canonical material hashed into the cluster id.
    #[must_use]
    pub fn canonical_material(&self) -> &str {
        &self.canonical_material
    }

    /// Returns the content-addressed cluster id for this key.
    #[must_use]
    pub fn content_hash(&self) -> ContentHash {
        ContentHash::from_canonical_material(FAILURE_SIGNATURE_KEY_DOMAIN, &self.canonical_material)
    }
}

/// Content-addressed identity of one triage result.
///
/// The findings ledger content address and active signature policy are both
/// included, so re-clustering the same ledger under the same policy resolves to
/// the same result identity while a policy change is a distinct artifact.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct FailureTriageResultIdentity {
    /// Content hash of the findings ledger being clustered.
    pub findings_ledger: ContentHash,
    /// Active policy used to project failure-signature keys.
    pub policy: SignaturePolicy,
}

impl FailureTriageResultIdentity {
    /// Builds a triage result identity from a findings ledger and policy.
    #[must_use]
    pub fn new(findings_ledger: ContentHash, policy: SignaturePolicy) -> Self {
        Self {
            findings_ledger,
            policy,
        }
    }

    /// Returns the canonical identity material.
    #[must_use]
    pub fn canonical_material(&self) -> String {
        failure_triage_result_identity_material(*self)
    }

    /// Returns the content-addressed triage result id.
    #[must_use]
    pub fn content_hash(&self) -> ContentHash {
        ContentHash::from_canonical_material(
            FAILURE_TRIAGE_RESULT_IDENTITY_DOMAIN,
            &self.canonical_material(),
        )
    }
}

/// A content-addressed set of finding reproduction artifacts.
///
/// Artifact-only ledgers retain only reproduction-artifact content hashes and
/// require an external engine-owned evidence bundle before they can be triaged.
/// Signed ledgers additionally carry the discovery-time failure signature for
/// each finding, letting offline triage cluster by recorded evidence without
/// inventing signatures in the CLI.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub struct FailureFindingsLedger {
    /// Artifact-only reproduction hashes in content-address order.
    pub artifacts: Vec<ContentHash>,
    /// Findings with discovery-time signatures in content-address order.
    pub findings: Vec<FailureClusterFinding>,
}

impl FailureFindingsLedger {
    /// Builds a deduplicated findings ledger from reproduction-artifact hashes.
    #[must_use]
    pub fn from_artifacts(artifacts: impl IntoIterator<Item = ContentHash>) -> Self {
        Self {
            artifacts: artifacts
                .into_iter()
                .collect::<BTreeSet<_>>()
                .into_iter()
                .collect(),
            findings: Vec::new(),
        }
    }

    /// Builds a signed findings ledger from discovery-time signatures.
    ///
    /// # Errors
    ///
    /// Returns [`EngineError::UnifiedOperationEvidenceMismatch`] if the same
    /// reproduction artifact is supplied with conflicting signature evidence.
    pub fn from_signed_findings(
        findings: impl IntoIterator<Item = FailureClusterFinding>,
    ) -> Result<Self, EngineError> {
        let mut ordered = BTreeMap::new();
        for finding in findings {
            match ordered.entry(finding.reproduction_artifact) {
                Entry::Vacant(entry) => {
                    entry.insert(finding);
                }
                Entry::Occupied(entry)
                    if entry.get().signature.report_material()
                        == finding.signature.report_material() => {}
                Entry::Occupied(_) => {
                    return Err(EngineError::UnifiedOperationEvidenceMismatch {
                        operation: "failure-findings-ledger",
                        reason: "same reproduction artifact has conflicting discovery signatures",
                    });
                }
            }
        }
        Ok(Self {
            artifacts: Vec::new(),
            findings: ordered.into_values().collect(),
        })
    }

    /// Returns the number of unique findings in this ledger.
    #[must_use]
    pub fn artifact_count(&self) -> usize {
        self.artifacts.len() + self.findings.len()
    }

    /// Returns signed findings consumable by the clustering engine.
    #[must_use]
    pub fn signed_findings(&self) -> &[FailureClusterFinding] {
        &self.findings
    }

    /// Returns canonical ledger material.
    #[must_use]
    pub fn canonical_material(&self) -> String {
        failure_findings_ledger_material(self)
    }

    /// Returns the content address of this ledger.
    #[must_use]
    pub fn content_hash(&self) -> ContentHash {
        ContentHash::from_bytes(&self.artifact_bytes())
    }

    /// Returns the deterministic bytes stored in the `DagStore`.
    #[must_use]
    pub fn artifact_bytes(&self) -> Vec<u8> {
        failure_triage_artifact_bytes(FAILURE_FINDINGS_LEDGER_DOMAIN, &self.canonical_material())
    }

    /// Stores this ledger artifact and reports whether it was already present.
    ///
    /// # Errors
    ///
    /// Returns [`DagStoreError`] when the store cannot query or persist the
    /// ledger bytes.
    pub fn store<S>(&self, store: &S) -> Result<FailureTriageStoredArtifact, DagStoreError>
    where
        S: DagStore + ?Sized,
    {
        store_failure_triage_artifact(store, &self.artifact_bytes())
    }
}

